def generalized_risk_stats(*,confids: npt.NDArray[Any],residuals: npt.NDArray[Any],idx_sorted_confids: npt.NDArray[Any] = None,) -> dict:
    """Computes the RC-point stats for the Generalized Risk.

    Returns:
        dict with keys: "coverages", "risks", "thresholds", "working_point_mask"
    """
    n = len(residuals)
    idx_sorted = (
        np.argsort(confids) if idx_sorted_confids is None else idx_sorted_confids
    )  # ascending scores
    residuals = residuals[idx_sorted]
    confidence = confids[idx_sorted]

    cov = n
    error_sum = sum(residuals)

    coverages = [1.0]
    risks = [error_sum / n]
    thresholds = [confidence[0]]
    working_point_mask = [True]
    current_min_risk = risks[0]

    for i in range(n - 1):
        cov -= 1
        error_sum -= residuals[i]
        risk = error_sum / n
        if confidence[i] != confidence[i + 1]:
            if risk < current_min_risk:
                working_point_mask.append(True)
                current_min_risk = risk
            else:
                working_point_mask.append(False)

            thresholds.append(confidence[i + 1])
            coverages.append(cov / n)
            risks.append(risk)

    coverages.append(0)
    working_point_mask.append(risks[-1] > 0)
    risks.append(0)

    return {
        "coverages": np.array(coverages),
        "risks": np.array(risks),
        "thresholds": np.array(thresholds),
        "working_point_mask": working_point_mask,
    }

class RiskCoverageStatsMixin:
    @cached_property
    def augrc(self) -> float:
        """Area under Generalized Risk Coverage Curve"""
        return self.evaluate_auc(risk="generalized-risk")

    def evaluate_auc(
        self,
        *,
        risk: str = None,
        coverages: npt.NDArray[Any] = None,
        risks: npt.NDArray[Any] = None,
        cov_min=0,
        cov_max=1,
        achievable=False,
        interpolation: str = "linear",
    ) -> float:
        if self.contains_nan:
            return np.nan

        if cov_max <= cov_min or cov_max <= 0 or cov_min >= 1:
            return 0.0

        assert (coverages is None) == (risks is None)
        if coverages is None:
            curve_stats = self.get_curve_stats(risk=risk)
            coverages = curve_stats["coverages"]
            risks = curve_stats["risks"]

        if achievable:
            if interpolation == "linear" and "generalized" not in risk:
                logging.warning(
                    "Achievable AURC values should be estimated with 'non-linear' "
                    f"interpolation. Currvently using: '{interpolation}' interpolation"
                )

            risks = risks[self.dominant_point_mask]
            coverages = coverages[self.dominant_point_mask]

        if interpolation == "linear" or "generalized" in risk:
            if cov_max != 1 or cov_min != 0:
                raise NotImplementedError()
            return -np.trapz(risks, coverages) * self.AUC_DISPLAY_SCALE

